public class Main {
    static int[] left, right, key;
    static int root = -1;
    static int nodeCount = 0;
    static final int MAX = 500005;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        left = new int[MAX];
        right = new int[MAX];
        key = new int[MAX];
        Arrays.fill(left, -1);
        Arrays.fill(right, -1);

        int n = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < n; i++) {
            String line = br.readLine().trim();
            String[] parts = line.split(" ");
            String op = parts[0];

            if (op.equals("insert")) {
                int k = Integer.parseInt(parts[1]);
                insert(k);
            } else if (op.equals("find")) {
                int k = Integer.parseInt(parts[1]);
                if (find(k)) {
                    sb.append("yes\n");
                } else {
                    sb.append("no\n");
                }
            } else if (op.equals("print")) {
                // inorder
                StringBuilder inorder = new StringBuilder();
                inorderTraversal(root, inorder);
                // preorder
                StringBuilder preorder = new StringBuilder();
                preorderTraversal(root, preorder);
                sb.append(inorder.toString().trim()).append("\n");
                sb.append(preorder.toString().trim()).append("\n");
            }
        }

        System.out.print(sb);
    }

    static void insert(int k) {
        int newNode = nodeCount++;
        key[newNode] = k;
        left[newNode] = -1;
        right[newNode] = -1;

        if (root == -1) {
            root = newNode;
            return;
        }

        int cur = root;
        while (true) {
            if (k < key[cur]) {
                if (left[cur] == -1) {
                    left[cur] = newNode;
                    break;
                } else {
                    cur = left[cur];
                }
            } else if (k > key[cur]) {
                if (right[cur] == -1) {
                    right[cur] = newNode;
                    break;
                } else {
                    cur = right[cur];
                }
            } else {
                // duplicate, don't insert
                nodeCount--; // revert
                break;
            }
        }
    }

    static boolean find(int k) {
        int cur = root;
        while (cur != -1) {
            if (k == key[cur]) return true;
            else if (k < key[cur]) cur = left[cur];
            else cur = right[cur];
        }
        return false;
    }

    static void inorderTraversal(int node, StringBuilder sb) {
        if (node == -1) return;
        inorderTraversal(left[node], sb);
        sb.append(" ").append(key[node]);
        inorderTraversal(right[node], sb);
    }

    static void preorderTraversal(int node, StringBuilder sb) {
        if (node == -1) return;
        sb.append(" ").append(key[node]);
        preorderTraversal(left[node], sb);
        preorderTraversal(right[node], sb);
    }
}

