def main():
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx]); idx += 1

    # BST using arrays for efficiency
    # Each node: left child, right child, key
    # Use -1 for null

    left = [-1] * 500005
    right = [-1] * 500005
    keys = [0] * 500005
    node_count = 0
    root = -1

    def new_node(k):
        nonlocal node_count
        keys[node_count] = k
        left[node_count] = -1
        right[node_count] = -1
        node_count += 1
        return node_count - 1

    def insert(k):
        nonlocal root
        if root == -1:
            root = new_node(k)
            return
        cur = root
        while True:
            if k < keys[cur]:
                if left[cur] == -1:
                    left[cur] = new_node(k)
                    break
                else:
                    cur = left[cur]
            elif k > keys[cur]:
                if right[cur] == -1:
                    right[cur] = new_node(k)
                    break
                else:
                    cur = right[cur]
            else:
                # Already exists
                break

    def find(k):
        cur = root
        while cur != -1:
            if k == keys[cur]:
                return True
            elif k < keys[cur]:
                cur = left[cur]
            else:
                cur = right[cur]
        return False

    inorder_result = []
    preorder_result = []

    def inorder(node):
        # Iterative inorder
        stack = []
        cur = node
        while True:
            while cur != -1:
                stack.append(cur)
                cur = left[cur]
            if not stack:
                break
            cur = stack.pop()
            inorder_result.append(keys[cur])
            cur = right[cur]

    def preorder(node):
        # Iterative preorder
        if node == -1:
            return
        stack = [node]
        while stack:
            cur = stack.pop()
            preorder_result.append(keys[cur])
            if right[cur] != -1:
                stack.append(right[cur])
            if left[cur] != -1:
                stack.append(left[cur])

    output = []

    for _ in range(n):
        op = input_data[idx]; idx += 1
        if op == 'insert':
            k = int(input_data[idx]); idx += 1
            insert(k)
        elif op == 'find':
            k = int(input_data[idx]); idx += 1
            if find(k):
