import sys

class Node:
    __slots__ = ("key", "left", "right")
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, key):
        if self.root is None:
            self.root = Node(key)
            return

        cur = self.root
        while True:
            if key < cur.key:
                if cur.left is None:
                    cur.left = Node(key)
                    return
                cur = cur.left
            else:
                if cur.right is None:
                    cur.right = Node(key)
                    return
                cur = cur.right

    def find(self, key):
        cur = self.root
        while cur is not None:
            if key == cur.key:
                return True
            elif key < cur.key:
                cur = cur.left
            else:
                cur = cur.right
        return False

    def inorder(self):
        res = []
        stack = []
        cur = self.root
        while stack or cur:
            while cur:
                stack.append(cur)
                cur = cur.left
            cur = stack.pop()
            res.append(cur.key)
            cur = cur.right
        return res

    def preorder(self):
        if self.root is None:
            return []
        res = []
        stack = [self.root]
        while stack:
            node = stack.pop()
            res.append(node.key)
            if node.right is not None:
                stack.append(node.right)
            if node.left is not None:
                stack.append(node.left)
        return res

def main():
    input = sys.stdin.readline
    n = int(input())
    bst = BST()
    out = []

    for _ in range(n):
        cmd = input().split()
        if cmd[0] == "insert":
            bst.insert(int(cmd[1]))
        elif cmd[0] == "find":
            out.append("yes" if bst.find(int(cmd[1])) else "no")
        else:  # print
            out.append(" " + " ".join(map(str, bst.inorder())))
            out.append(" " + " ".join(map(str, bst.preorder())))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
